const FINANCIAL_REMINDERS_KEY = 'budgetFinancialRemindersV1';
function getFinancialReminders(){ try { const x=JSON.parse(localStorage.getItem(FINANCIAL_REMINDERS_KEY)||'[]'); return Array.isArray(x)?x:[]; } catch(e){ return []; } }
function reminderTypeLabel(t){ return ({iOwe:'אני חייב',owedToMe:'חייבים לי',payment:'תשלום עתידי',income:'הכנסה צפויה',task:'משימה פיננסית',other:'אחר'})[t]||'אחר'; }
function resetReminderForm(){ ['reminderEditId','reminderTitle','reminderPerson','reminderAmount','reminderDueDate','reminderNote'].forEach(id=>{const e=document.getElementById(id);if(e)e.value='';}); const t=document.getElementById('reminderType');if(t)t.value='iOwe'; }
function saveFinancialReminder(ev){ ev.preventDefault(); const id=document.getElementById('reminderEditId').value; const arr=getFinancialReminders(); const item={id:id||('r'+Date.now()),title:document.getElementById('reminderTitle').value.trim(),type:document.getElementById('reminderType').value,person:document.getElementById('reminderPerson').value.trim(),amount:Number(document.getElementById('reminderAmount').value||0),dueDate:document.getElementById('reminderDueDate').value,note:document.getElementById('reminderNote').value.trim(),done:false,updatedAt:new Date().toISOString()}; const ix=arr.findIndex(x=>x.id===id); if(ix>=0)item.done=!!arr[ix].done,arr[ix]=item;else arr.unshift(item); localStorage.setItem(FINANCIAL_REMINDERS_KEY,JSON.stringify(arr)); resetReminderForm();renderFinancialReminders(); }
function editFinancialReminder(id){ const x=getFinancialReminders().find(r=>r.id===id);if(!x)return; document.getElementById('reminderEditId').value=x.id;document.getElementById('reminderTitle').value=x.title||'';document.getElementById('reminderType').value=x.type||'other';document.getElementById('reminderPerson').value=x.person||'';document.getElementById('reminderAmount').value=x.amount||'';document.getElementById('reminderDueDate').value=x.dueDate||'';document.getElementById('reminderNote').value=x.note||'';document.getElementById('reminderTitle').focus(); }
function toggleFinancialReminder(id){ const a=getFinancialReminders(),x=a.find(r=>r.id===id);if(x){x.done=!x.done;localStorage.setItem(FINANCIAL_REMINDERS_KEY,JSON.stringify(a));renderFinancialReminders();} }
function deleteFinancialReminder(id){ if(!confirm('למחוק את התזכורת?'))return; localStorage.setItem(FINANCIAL_REMINDERS_KEY,JSON.stringify(getFinancialReminders().filter(r=>r.id!==id)));renderFinancialReminders(); }
function renderFinancialReminders(){ const a=getFinancialReminders(),open=a.filter(x=>!x.done),money=n=>'₪'+Number(n||0).toLocaleString('he-IL',{maximumFractionDigits:2}); const owe=open.filter(x=>x.type==='iOwe').reduce((s,x)=>s+Number(x.amount||0),0),owed=open.filter(x=>x.type==='owedToMe').reduce((s,x)=>s+Number(x.amount||0),0); const e1=document.getElementById('remindersIOwe'),e2=document.getElementById('remindersOwedToMe'),e3=document.getElementById('remindersOpenCount'),box=document.getElementById('financialRemindersList');if(e1)e1.textContent=money(owe);if(e2)e2.textContent=money(owed);if(e3)e3.textContent=open.length;if(!box)return;if(!a.length){box.innerHTML='<div class="text-center text-slate-400 py-8">אין עדיין תזכורות. אפשר להוסיף את הראשונה למעלה.</div>';return;} box.innerHTML=a.slice().sort((x,y)=>(x.done-y.done)||String(x.dueDate||'9999').localeCompare(String(y.dueDate||'9999'))).map(x=>`<div class="rounded-xl border ${x.done?'bg-slate-50 border-slate-200 opacity-60':'bg-white border-slate-200'} p-4"><div class="flex flex-wrap justify-between gap-3"><div><div class="font-extrabold text-slate-900 ${x.done?'line-through':''}">${escapeHtml(x.title||'')}</div><div class="text-xs text-slate-500 mt-1">${reminderTypeLabel(x.type)}${x.person?' • '+escapeHtml(x.person):''}${x.dueDate?' • יעד: '+new Date(x.dueDate+'T12:00:00').toLocaleDateString('he-IL'):''}</div>${x.note?`<div class="text-sm text-slate-600 mt-2">${escapeHtml(x.note)}</div>`:''}</div><div class="text-left">${x.amount?`<div class="font-extrabold text-lg">${money(x.amount)}</div>`:''}<div class="flex gap-2 mt-2"><button onclick="toggleFinancialReminder('${x.id}')" class="text-xs px-2 py-1 rounded-lg bg-emerald-50 text-emerald-700 font-bold">${x.done?'פתח מחדש':'טופל'}</button><button onclick="editFinancialReminder('${x.id}')" class="text-xs px-2 py-1 rounded-lg bg-blue-50 text-blue-700 font-bold">עריכה</button><button onclick="deleteFinancialReminder('${x.id}')" class="text-xs px-2 py-1 rounded-lg bg-rose-50 text-rose-700 font-bold">מחיקה</button></div></div></div></div>`).join(''); }

